// One forwarded email = one deal. Pulls the email text and finds the contract PDF among the attachments.
const strip = h => String(h || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>|<\/p>|<\/div>/gi, '\n')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
return $input.all().map(item => {
  const j = item.json;
  const bin = item.binary || {};
  const keys = Object.keys(bin);
  const pdfKey = keys.find(k => /pdf/i.test(bin[k].mimeType || '') || /\.pdf$/i.test(bin[k].fileName || '')) || '';
  const other = keys.filter(k => k !== pdfKey).map(k => bin[k].fileName || k);
  return { json: { subject: String(j.subject || '').replace(/^(fwd?|fw):\s*/i, ''), from: j.from || '',
    emailText: String(j.textPlain || j.text || strip(j.textHtml || j.html)).trim(),
    pdfKey: pdfKey || 'none', contractFile: pdfKey ? bin[pdfKey].fileName || 'contract.pdf' : '', otherFiles: other },
    binary: item.binary };
});

// Two questions for the local AI: what the emails agreed, and what the contract says. Same fields for both.
const MODEL = 'qwen/qwen3.5-9b';   // thinking off in each request: the answers need the token budget
const CAP = 14000; // characters per text, so it fits the model's context window
const KEY = /(fee|pay|paid|\$|usd|eur|invoice|net ?\d|rate|compens|deliverabl|post|reel|video|stor(y|ies)|deadline|due|date|usage|licen[cs]|rights?|perpetu|exclusiv|compet|revision|approv|terminat|cancel|kill|own|intellectual|whitelist|boost|ads?\b|spark|term\b|months?|days?|weeks?)/i;
function focus(text) {
  const t = String(text || '').replace(/\r/g, '');
  if (t.length <= CAP) return { text: t, cut: false };
  // Long text: keep the paragraphs that talk about money, rights, deliverables and dates
  const parts = t.split(/\n\s*\n|(?<=\.)\s{2,}/).filter(p => KEY.test(p));
  let out = '';
  for (const p of parts) { if (out.length + p.length > CAP) break; out += p.trim() + '\n\n'; }
  return { text: out || t.slice(0, CAP), cut: true };
}
const FIELD = { type: 'object', properties: { value: { type: ['string', 'null'] }, quote: { type: ['string', 'null'] } }, required: ['value', 'quote'] };
const NUM = { type: 'object', properties: { value: { type: ['number', 'null'] }, quote: { type: ['string', 'null'] } }, required: ['value', 'quote'] };
const FIELDS = {
  fee: NUM, currency: FIELD, payment_due_days: NUM, deliverables: FIELD, deliverable_count: NUM, deadlines: FIELD,
  usage_rights: FIELD, paid_ads_or_whitelisting: FIELD, exclusivity: FIELD, revisions: FIELD, approval: FIELD,
  cancellation_or_kill_fee: FIELD, content_ownership: FIELD
};
const schema = { type: 'object', properties: FIELDS, required: Object.keys(FIELDS) };
const HELP = 'fee = total money paid to the creator as a number. payment_due_days = days after invoice or posting until payment (Net 30 = 30). ' +
  'deliverables = what the creator must make and post, in short words. deliverable_count = number of pieces of content. ' +
  'usage_rights = how long and where the brand may use the content. paid_ads_or_whitelisting = whether the brand can run the content as ads or from the creator\'s account. ' +
  'exclusivity = any ban on working with competitors, with how long. content_ownership = who owns the content.';
const ask = (who, text) => ({ model: MODEL, reasoning_effort: 'none', chat_template_kwargs: { enable_thinking: false }, temperature: 0, max_tokens: 1500,
  messages: [
    { role: 'system', content: 'You read creator brand-deal documents and pull out the terms. Reply only with JSON. Use null when the text does not say. quote = a short exact quote from the text, max 25 words. Never guess.' },
    { role: 'user', content: `${HELP}\n\n${who}\n\n---\n${text}\n---` }],
  response_format: { type: 'json_schema', json_schema: { name: 'deal_terms', strict: true, schema } } });
return $input.all().map((item, idx) => {
  const src = $('Find the contract').all()[idx].json;
  const contract = String(item.json.text || '').trim();
  const e = focus(src.emailText), c = focus(contract);
  return { json: { ...src, contractRead: contract.length > 200, emailCut: e.cut, contractCut: c.cut,
    llmEmail: ask('These are the emails between the creator and the brand. Use the LATEST terms both sides agreed to. Ignore quoted older versions that were changed later.', e.text),
    llmContract: ask('This is the contract.', c.text) } };
});

// Compares the two sets of terms. Numbers are compared here; wording is sent to the local AI as same/different questions.
const parse = r => { try { const t = r.choices[0].message.content; return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { return null; } };
const LABEL = { fee: 'Fee', currency: 'Currency', payment_due_days: 'Payment timing (days)', deliverables: 'Deliverables', deliverable_count: 'Number of pieces',
  deadlines: 'Deadlines', usage_rights: 'Usage rights', paid_ads_or_whitelisting: 'Paid ads / whitelisting', exclusivity: 'Exclusivity',
  revisions: 'Revisions', approval: 'Approval process', cancellation_or_kill_fee: 'Cancellation / kill fee', content_ownership: 'Who owns the content' };
const NUMERIC = ['fee', 'payment_due_days', 'deliverable_count'];
const norm = x => String(x).toLowerCase().replace(/[^a-z0-9]/g, '');
const has = f => f && f.value !== null && f.value !== undefined && String(f.value).trim() !== '';
const prev = $('Build extraction requests').all().map(i => i.json);
const emailRes = $('Local AI: terms from emails').all().map(i => i.json);
return $input.all().map((item, idx) => {
  const p = prev[idx];
  const E = parse(emailRes[idx]) || {}, C = parse(item.json) || {};
  const rows = [], pairs = [];
  for (const k of Object.keys(LABEL)) {
    const e = E[k], c = C[k];
    const row = { field: k, label: LABEL[k], email: has(e) ? e : null, contract: has(c) ? c : null, result: '' };
    if (!row.email && !row.contract) row.result = 'neither';
    else if (row.email && !row.contract) row.result = 'missing';
    else if (!row.email && row.contract) row.result = 'contract only';
    else if (NUMERIC.includes(k)) row.result = Number(e.value) === Number(c.value) ? 'match' : 'mismatch';
    else if (norm(e.value) === norm(c.value)) row.result = 'match';
    else { row.result = 'check'; pairs.push({ id: k, email: String(e.value), contract: String(c.value) }); }
    rows.push(row);
  }
  // Red flags in the contract itself, whatever the emails said
  const flags = [];
  const v = k => (has(C[k]) ? String(C[k].value) : '');
  if (/perpetu|in perpetuity|forever|unlimited|irrevocable/i.test(v('usage_rights'))) flags.push(['Usage rights look permanent', C.usage_rights]);
  if (/assign|work.?for.?hire|all right|brand owns|company owns|exclusive owner/i.test(v('content_ownership'))) flags.push(['You may be giving up ownership of the content', C.content_ownership]);
  if (/yes|may|can|right to|whitelist|spark|boost|paid/i.test(v('paid_ads_or_whitelisting')) && !/no\b|not|without/i.test(v('paid_ads_or_whitelisting'))) flags.push(['Brand can run your content as paid ads. That usually earns an extra fee', C.paid_ads_or_whitelisting]);
  if (has(C.payment_due_days) && Number(C.payment_due_days.value) > 30) flags.push([`Payment comes ${C.payment_due_days.value} days after invoice`, C.payment_due_days]);
  const ex = v('exclusivity'); const exDays = (() => { const m = ex.match(/(\d+)\s*(day|week|month|year)/i); if (!m) return 0; return Number(m[1]) * { day: 1, week: 7, month: 30, year: 365 }[m[2].toLowerCase()]; })();
  if (ex && !/no exclusiv|none|not exclusive/i.test(ex) && (exDays === 0 || exDays > 30)) flags.push([exDays ? `Exclusivity lasts about ${exDays} days` : 'Exclusivity with no clear end date', C.exclusivity]);
  if (/unlimited|as many|until satisf/i.test(v('revisions'))) flags.push(['Unlimited revisions', C.revisions]);
  if (!has(C.cancellation_or_kill_fee)) flags.push(['No kill fee if the brand cancels after you start', null]);
  const judge = pairs.length ? { model: 'qwen/qwen3.5-9b', reasoning_effort: 'none', chat_template_kwargs: { enable_thinking: false }, temperature: 0, max_tokens: 800,
    messages: [{ role: 'system', content: 'You compare deal terms. Reply only with JSON.' },
      { role: 'user', content: 'For each pair, say "same" if the contract matches what the emails agreed (wording can differ), or "different" if a number, amount, length of time, channel, count or obligation differs. Add a short reason, max 15 words.\n\n' + JSON.stringify(pairs) }],
    response_format: { type: 'json_schema', json_schema: { name: 'judgement', strict: true, schema: { type: 'object', properties: { results: { type: 'array', items: { type: 'object',
      properties: { id: { type: 'string' }, verdict: { type: 'string', enum: ['same', 'different'] }, reason: { type: 'string' } }, required: ['id', 'verdict', 'reason'] } } }, required: ['results'] } } } } : null;
  return { json: { ...p, llmEmail: undefined, llmContract: undefined, aiOk: !!(parse(emailRes[idx]) && parse(item.json)), rows, flags, judge } };
});

// Turns the comparison into a plain email for Graham. Flags only, never legal advice.
const parse = r => { try { const t = r.choices[0].message.content; return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { return null; } };
const prev = $('Compare terms').all().map(i => i.json);
const q = f => (f && f.quote ? `"${String(f.quote).trim()}"` : (f ? String(f.value) : ''));
return $input.all().map((item, idx) => {
  const p = prev[idx];
  const verdicts = {};
  ((parse(item.json) || {}).results || []).forEach(r => verdicts[r.id] = r);
  const issues = [], ok = [], missing = [];
  for (const r of p.rows) {
    let res = r.result;
    if (res === 'check') res = verdicts[r.field] ? (verdicts[r.field].verdict === 'same' ? 'match' : 'mismatch') : 'unsure';
    if (res === 'mismatch' || res === 'unsure') issues.push(`- ${r.label}${res === 'unsure' ? ' (check by eye)' : ''}\n  Emails: ${q(r.email)}\n  Contract: ${q(r.contract)}${verdicts[r.field] ? `\n  Why: ${verdicts[r.field].reason}` : ''}`);
    else if (res === 'missing') missing.push(`- ${r.label}: agreed in email (${q(r.email)}) but not in the contract`);
    else if (res === 'match') ok.push(r.label);
  }
  const lines = [];
  if (!p.contractFile) lines.push('No PDF contract was attached, so only the emails were read. Forward the thread again with the contract PDF attached.', '');
  else if (!p.contractRead) lines.push(`Couldn't read text from ${p.contractFile}. If it's a scan, ask the brand for a text PDF.`, '');
  if (!p.aiOk) lines.push('The local AI (LM Studio) did not answer, so this check is incomplete. Make sure LM Studio is running, then forward the thread again.', '');
  lines.push(issues.length ? `DIFFERENT FROM WHAT YOU AGREED (${issues.length})` : 'Nothing in the contract contradicts the emails.', ...issues, '');
  if (missing.length) lines.push(`AGREED BUT MISSING FROM THE CONTRACT (${missing.length})`, ...missing, '');
  if (p.flags.length) lines.push(`WORTH A SECOND LOOK (${p.flags.length})`, ...p.flags.map(([t, f]) => `- ${t}${f ? `\n  Contract: ${q(f)}` : ''}`), '');
  if (ok.length) lines.push(`MATCHES: ${ok.join(', ')}`, '');
  if (p.emailCut || p.contractCut) lines.push('Long document: only the parts about money, rights, deliverables and dates were checked.', '');
  lines.push('This is an automatic check that flags differences to ask about. It is not legal advice. For anything big, have a lawyer read the contract.');
  const n = issues.length + missing.length;
  return { json: { subject: `Contract check: ${n ? n + ' to fix' : 'no differences'}${p.flags.length ? `, ${p.flags.length} to review` : ''} | ${p.subject}`.slice(0, 180), text: lines.join('\n') } };
});
